  const schedules=section('Saved schedule snapshots');for(const s of saved){const row=el('div');row.append(el('h3',s.name),el('p',`${s.event_type} · ${s.event_time} · ${s.ground_station} / ${s.mission_location} · ${s.assignment_count} assignments`));button(row,'Open simulator',()=>window.open(`/simulator/${s.job_id}?revision=${encodeURIComponent(s.revision)}`,'_blank','noopener'));button(row,'Open mission inputs',async()=>{window.applyMissionFields(await api(`jobs/${s.job_id}/inputs`));d.close();});button(row,'Files & graphs',async()=>{const info=await api('saved-missions/'+s.id),files=dialog(s.name);for(const f of info.files){const a=el('a',f);a.href=`/api/saved-missions/${s.id}/files/${f}?inline=1`;a.target='_blank';a.rel='noopener';const p=el('p');p.append(a);files.append(p);}});schedules.append(row);}
  const past=section('Previous jobs');let offset=0;const rows=el('div');past.append(rows);async function page(){const jobs=await api('jobs?limit=25&offset='+offset);rows.replaceChildren();for(const j of jobs){const p=el('p',`${j.mission_name} · ${j.state}`);button(p,'Open results',async()=>{selectedJob=j.id;renderedJob=null;await refreshJobs();d.close();});button(p,'Reuse inputs',async()=>{window.applyMissionFields(await api(`jobs/${j.id}/inputs`));d.close();});rows.append(p);}}button(past,'Previous page',async()=>{offset=Math.max(0,offset-25);await page();});button(past,'Next page',async()=>{offset+=25;await page();});await page();
  const calendar=section('Mission calendar · UTC'),nav=el('div'),grid=el('div');calendar.open=true;calendar.append(el('p','To remove an event, expand Saved mission inputs and choose Delete event.'));grid.className='calendar-grid';calendar.append(nav,grid);let month=new Date();month=new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth(),1));const events=[...presets.map(p=>({presetId:p.id,name:p.mission.mission_name,time:p.mission.event_time,load:()=>window.applyMissionFields(p.mission)})),...saved.map(s=>({name:s.name,time:s.event_time,load:()=>{selectedJob=s.job_id;renderedJob=null;refreshJobs();}}))];
  function openCalendarEvent(event){const detail=dialog(event.name);detail.append(el('p',event.time.replace('T',' ').replace('Z',' UTC')));button(detail,'Open mission',()=>{event.load();detail.close();d.close();});if(event.presetId)button(detail,'Delete event',async()=>{if(!confirm('Delete this event from the shared calendar? Past schedules remain.'))return;await api(`presets/${event.presetId}/archive`,{});window.dispatchEvent(new Event('presetsChanged'));await refreshBoard();detail.close();d.close();await library();});}
  function draw(){nav.replaceChildren();button(nav,'‹ Previous month',()=>{month.setUTCMonth(month.getUTCMonth()-1);draw();});nav.append(el('strong',month.toISOString().slice(0,7)));button(nav,'Next month ›',()=>{month.setUTCMonth(month.getUTCMonth()+1);draw();});grid.replaceChildren();for(const name of ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'])grid.append(el('strong',name));for(let i=0;i<month.getUTCDay();i++)grid.append(el('div'));const days=new Date(Date.UTC(month.getUTCFullYear(),month.getUTCMonth()+1,0)).getUTCDate();for(let day=1;day<=days;day++){const cell=el('div',String(day));cell.className='calendar-day';const stamp=month.toISOString().slice(0,7)+'-'+String(day).padStart(2,'0');for(const e of events.filter(e=>e.time.startsWith(stamp)))button(cell,`${e.time.slice(11,16)} ${e.name}`,()=>openCalendarEvent(e));grid.append(cell);}}draw();
